insert into public.businesses (id, locality_id, name, slug, short_description, description, phone, whatsapp, email, website, instagram, facebook, address, latitude, longitude, show_exact_address, logo_url, cover_image_url, is_home_business, provides_delivery, provides_home_service, accessibility, kosher, verified, active, featured, is_demo, recommendation_count, created_at, updated_at) values ('00000000-0000-4000-8000-000000000401', '00000000-0000-4000-8000-000000000001', 'פיצריית הכיכר', 'pizzeria-hakikar', 'פיצה במגש, משלוחים ואיסוף עצמי בכל עתלית.', 'מטבח קטן עם תנור חם ובצק שמכינים כאן כל בוקר. מתאים למשפחה, לערב חברים או למגש שאפשר לאסוף בדרך הביתה. בימי שישי כדאי להזמין מוקדם.', '050-000-0101', '050-000-0101', null, null, null, null, 'רחוב הזית 14, עתלית', 32.6861, 34.9425, true, null, null, false, true, false, false, false, true, true, true, true, 0, '2026-03-15T09:00:00.000Z', '2026-03-15T09:00:00.000Z') on conflict (id) do nothing;
insert into public.businesses (id, locality_id, name, slug, short_description, description, phone, whatsapp, email, website, instagram, facebook, address, latitude, longitude, show_exact_address, logo_url, cover_image_url, is_home_business, provides_delivery, provides_home_service, accessibility, kosher, verified, active, featured, is_demo, recommendation_count, created_at, updated_at) values ('00000000-0000-4000-8000-000000000402', '00000000-0000-4000-8000-000000000001', 'קפה מורן', 'cafe-moran', 'קפה, מאפים ובוקר רגוע במרכז עתלית.', 'מקום לשבת עם מחשב, עם הילדים או סתם לחכות למישהו. יש ארוחות בוקר, עוגת יום הולדת להזמנה מראש ופינה נגישה.', '050-000-0102', '050-000-0102', null, null, 'https://instagram.com/cafe.moran.demo', null, 'רחוב הרימון 3, עתלית', 32.6912, 34.9406, true, null, null, false, false, false, true, false, true, true, true, true, 0, '2026-04-02T09:00:00.000Z', '2026-04-02T09:00:00.000Z') on conflict (id) do nothing;
insert into public.businesses (id, locality_id, name, slug, short_description, description, phone, whatsapp, email, website, instagram, facebook, address, latitude, longitude, show_exact_address, logo_url, cover_image_url, is_home_business, provides_delivery, provides_home_service, accessibility, kosher, verified, active, featured, is_demo, recommendation_count, created_at, updated_at) values ('00000000-0000-4000-8000-000000000403', '00000000-0000-4000-8000-000000000001', 'המטבח של רינה', 'rina-kitchen', 'אוכל ביתי במגשים ומשלוחים בתוך היישוב.', 'תבשילים, סלטים ומגשים לשישי או לאירוח קטן. הכל נעשה בבית, בתיאום מראש, ומגיע עד הדלת בתוך עתלית. אין חנות פתוחה לרחוב.', '050-000-0103', '050-000-0103', null, null, null, null, null, null, null, false, null, null, true, true, false, false, false, false, true, true, true, 0, '2026-04-22T09:00:00.000Z', '2026-04-22T09:00:00.000Z') on conflict (id) do nothing;
